import path from "node:path";

/** Generated byte lengths, matching scripts/cloud-install.sh (openssl rand -base64 32 and 24). */
export const CAL_GENERATED_KEY_BYTES = { NEXTAUTH_SECRET: 32, CALENDSO_ENCRYPTION_KEY: 24 } as const;

/** The Cal database volume. Compose names it `<project>_<volume>` (project qa-harness-cal, volume db_data). */
export const CAL_DB_VOLUME = "qa-harness-cal_db_data";

/** "missing" = the key is absent; "placeholder" = present with an empty value (as .env.example ships it); "real" = non-empty. */
export type CalEnvValueState = "missing" | "placeholder" | "real";

export function classifyCalEnvValue(value: string | undefined): CalEnvValueState {
  if (value === undefined) {
    return "missing";
  }
  const trimmed = value.trim();
  if (trimmed === "" || trimmed === '""' || trimmed === "''") {
    return "placeholder";
  }
  return "real";
}

/** Replaces "http://localhost:3000" only, every occurrence. Used on creation, as cloud-install.sh:113 does. */
export function rewriteLocalhostToLoopback(text: string): string {
  return text.split("http://localhost:3000").join("http://127.0.0.1:3000");
}

export interface CalEnvFs {
  existsSync(p: string): boolean;
  readFileSync(p: string, encoding: "utf8"): string;
  writeFileSync(p: string, data: string, opts: { mode: number; flag?: string }): void;
  copyFileSync(from: string, to: string): void;
  chmodSync(p: string, mode: number): void;
  renameSync(from: string, to: string): void;
  rmSync(p: string, opts: { force: boolean }): void;
}

export interface EnsureCalRootEnvOptions {
  productRoot: string;
  fs: CalEnvFs;
  randomBytes(size: number): Buffer;
  /** True when qa-harness-cal_db_data exists. */
  calDbVolumeExists(): boolean;
}

export interface EnsureCalRootEnvResult {
  readonly createdFromExample: boolean;
  /** Names only, e.g. ["NEXTAUTH_SECRET"]. Never values. */
  readonly generated: readonly string[];
}

const ENV_MODE = 0o600;

/** The value of the first `KEY=` line, or undefined when the key has no line. */
function readKeyValue(text: string, key: string): string | undefined {
  const prefix = `${key}=`;
  for (const line of text.split("\n")) {
    if (line.startsWith(prefix)) {
      return line.slice(prefix.length).replace(/\r$/, "");
    }
  }
  return undefined;
}

/** Removes every `KEY=` line and appends `KEY=value`. Other lines keep their order. */
function withKeyReplaced(text: string, key: string, value: string): string {
  const prefix = `${key}=`;
  const kept = text.split("\n").filter((line) => !line.startsWith(prefix)).join("\n");
  const base = kept === "" || kept.endsWith("\n") ? kept : `${kept}\n`;
  return `${base}${key}=${value}\n`;
}

/**
 * Decides everything in memory first, then writes once. Throws CAL_ENCRYPTION_KEY_VOLUME_EXISTS before any write when a
 * new CALENDSO_ENCRYPTION_KEY would be generated over an existing database volume. Writes only when something changed,
 * with mode 600. Values are never logged or returned.
 */
export function ensureCalRootEnv(opts: EnsureCalRootEnvOptions): EnsureCalRootEnvResult {
  const envPath = path.join(opts.productRoot, ".env");
  const examplePath = path.join(opts.productRoot, ".env.example");

  let text: string;
  let createdFromExample = false;
  if (opts.fs.existsSync(envPath)) {
    text = opts.fs.readFileSync(envPath, "utf8");
  } else {
    if (!opts.fs.existsSync(examplePath)) {
      throw new Error(`Cal .env.example missing at ${examplePath}; cannot create the Cal root .env.`);
    }
    text = rewriteLocalhostToLoopback(opts.fs.readFileSync(examplePath, "utf8"));
    createdFromExample = true;
  }

  const generated: string[] = [];
  let next = text;
  for (const key of Object.keys(CAL_GENERATED_KEY_BYTES) as (keyof typeof CAL_GENERATED_KEY_BYTES)[]) {
    if (classifyCalEnvValue(readKeyValue(next, key)) === "real") {
      continue;
    }
    generated.push(key);
    // Value is computed here and never leaves this function.
    next = withKeyReplaced(next, key, opts.randomBytes(CAL_GENERATED_KEY_BYTES[key]).toString("base64"));
  }

  if (generated.includes("CALENDSO_ENCRYPTION_KEY") && opts.calDbVolumeExists()) {
    throw new Error(
      `CAL_ENCRYPTION_KEY_VOLUME_EXISTS: ${envPath} has no CALENDSO_ENCRYPTION_KEY and the Cal database volume ${CAL_DB_VOLUME} exists. A new key cannot decrypt rows written under the old one. Reset with CAL_DOWN_VOLUMES=1 npm run down -- cal, or restore the old .env.`,
    );
  }

  if (generated.length === 0) {
    return { createdFromExample: false, generated: [] };
  }
  // Write a 600 temp file beside .env, then rename it over .env. A reader never sees a partial file.
  const tmp = `${envPath}.harness-tmp-${process.pid}`;
  let tmpStarted = false;
  try {
    tmpStarted = true;
    opts.fs.writeFileSync(tmp, next, { mode: ENV_MODE, flag: "wx" });
    opts.fs.chmodSync(tmp, ENV_MODE);
    opts.fs.renameSync(tmp, envPath);
  } catch (err) {
    if (tmpStarted) {
      opts.fs.rmSync(tmp, { force: true });
    }
    throw err;
  }
  return { createdFromExample, generated };
}

/**
 * Runs the writer first, then compose up. Injected so the order is unit-tested:
 * ensureEnv must be recorded before composeUp (see 1.5, call order).
 */
export async function calUpPrelude(deps: {
  ensureEnv(): void;
  composeUp(): Promise<void>;
}): Promise<void> {
  deps.ensureEnv();
  await deps.composeUp();
}

/** ["-v"] only when CAL_DOWN_VOLUMES is exactly "1". */
export function calDownArgs(env: NodeJS.ProcessEnv): readonly string[] {
  return env.CAL_DOWN_VOLUMES === "1" ? ["-v"] : [];
}
